statement:
One table holds DNA samples:

- `Samples(sample_id, dna_sequence, species)`: one row per sample; `sample_id` is unique. `dna_sequence` is a non-empty string of the uppercase letters `A`, `T`, `G` and `C`.

Report **every** sample with its `sample_id`, `dna_sequence` and `species`, plus four flags, each `1` when the pattern is present and `0` otherwise:

- `has_start`: the sequence begins with `ATG`;
- `has_stop`: the sequence ends with `TAA`, `TAG` or `TGA`;
- `has_atat`: `ATAT` occurs anywhere in the sequence;
- `has_ggg`: the sequence contains three or more `G` in a row.

Order the rows by `sample_id` ascending.

validator:
function validate(input) {
  const [{ Samples = [] }] = input;
  const ids = new Set();
  for (const [id, dna] of Samples) {
    if (id === null) return 'Every sample needs a sample_id.';
    if (ids.has(id)) return `sample_id ${id} appears twice.`;
    ids.add(id);
    if (dna === null || !/^[ATGC]+$/.test(dna)) return `dna_sequence ${dna} must use only A, T, G and C.`;
  }
  return null;
}

generator:
function generate(rand, size) {
  const pick = list => list[Math.floor(rand() * list.length)];
  const random = n => Array.from({ length: n }, () => pick(['A', 'T', 'G', 'C'])).join('');
  const sequence = () => {
    let s = random(Math.floor(rand() * (size === 'small' ? 8 : 14)));
    if (rand() < 0.25) { const at = Math.floor(rand() * (s.length + 1)); s = s.slice(0, at) + pick(['ATAT', 'ATA', 'TATA', 'ATATAT']) + s.slice(at); }
    if (rand() < 0.25) { const at = Math.floor(rand() * (s.length + 1)); s = s.slice(0, at) + pick(['GG', 'GGG', 'GGGG']) + s.slice(at); }
    if (rand() < 0.35) s = pick(['ATG', 'AT', 'TG', 'ATC']) + s;
    if (rand() < 0.35) s += pick(['TAA', 'TAG', 'TGA', 'TAC', 'AGA', 'TGG']);
    return s || pick(['A', 'ATG', 'TAA']);
  };
  const rows = size === 'small' ? Math.floor(rand() * 9) : 2000;
  const ids = Array.from({ length: rows }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  const Samples = ids.map(id => [id, sequence(), pick(['Human', 'Mouse', 'Zebrafish', 'Yeast'])]);
  return [{ Samples }];
}
